import os, json, math, numpy as np

IN_JSON = 'storage/shared/agents/zephyr/ven_ridge_analysis.json'
OUT_DIR = 'storage/shared/agents/kairos/VEN/tables'
os.makedirs(OUT_DIR, exist_ok=True)

def deep_items(obj, path=()):
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from deep_items(v, path + (str(k),))
    elif isinstance(obj, (list, tuple)):
        for i, v in enumerate(obj):
            yield from deep_items(v, path + (f"[{i}]",))
    else:
        yield path, obj

def find_arrays(d, name_substrs=('balanced','discovery','grounded')):
    arrays = {k: [] for k in name_substrs}
    for path, v in deep_items(d):
        # candidate 2D arrays (list of lists or numpy-like)
        try:
            if isinstance(v, list) and v and isinstance(v[0], (list, tuple)):
                flat_path = ".".join(path).lower()
                for mode in name_substrs:
                    if mode in flat_path:
                        arrays[mode].append(v)
        except Exception:
            pass
    return arrays

def find_axis(d, key_substr):
    # return first 1D array under paths containing key_substr
    for path, v in deep_items(d):
        flat_path = ".".join(path).lower()
        if key_substr in flat_path and isinstance(v, list) and v and not isinstance(v[0], (list, tuple)):
            try:
                arr = [float(x) for x in v]
                return arr
            except Exception:
                continue
    return None

def summarize_arrays(arrs, thresh=0.75):
    # arrs: list of 2D lists
    if not arrs:
        return None
    # Prefer the largest array by total size
    best = max(arrs, key=lambda a: len(a)*len(a[0]) if (a and isinstance(a[0], (list, tuple))) else 0)
    Z = np.array(best, dtype=float)
    return {
        'max': float(np.nanmax(Z)),
        'mean': float(np.nanmean(Z)),
        'ridge_count': int(np.sum(Z >= thresh)),
        'total': int(Z.size),
        'frac_ridge': float(np.sum(Z >= thresh)/Z.size if Z.size else 0.0)
    }

def argmax_coords(Z):
    i, j = np.unravel_index(np.nanargmax(Z), Z.shape)
    return int(i), int(j), float(np.nanmax(Z))

def main():
    # Load JSON
    try:
        with open(IN_JSON, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        print(f"[error] cannot read {IN_JSON}: {e}")
        # still write empty placeholders to not break pipeline
        with open(os.path.join(OUT_DIR, 'ven_ridge_mode_table.csv'), 'w', encoding='utf-8') as f:
            f.write('mode,max,mean,ridge_count,total,frac_ridge,threshold\n')
        with open(os.path.join(OUT_DIR, 'ven_ridge_contours_summary.txt'), 'w', encoding='utf-8') as f:
            f.write('No ridge analysis JSON available.\n')
        print(f"[artifacts] {os.path.join(OUT_DIR, 'ven_ridge_mode_table.csv')} | {os.path.join(OUT_DIR, 'ven_ridge_contours_summary.txt')}")
        return

    arrays = find_arrays(data, ('balanced','discovery','grounded'))
    r_axis = find_axis(data, 'r') or find_axis(data, 'ratio') or find_axis(data, 'x')
    a_axis = find_axis(data, 'alpha') or find_axis(data, 'y')

    # Mode table
    table_csv = os.path.join(OUT_DIR, 'ven_ridge_mode_table.csv')
    with open(table_csv, 'w', encoding='utf-8') as f:
        f.write('mode,max,mean,ridge_count,total,frac_ridge,threshold\n')
        for mode in ('balanced','discovery','grounded'):
            summ = summarize_arrays(arrays.get(mode, []), thresh=0.75)
            if summ is None:
                f.write(f"{mode},,,0,0,0.0,0.75\n")
            else:
                f.write(f"{mode},{summ['max']},{summ['mean']},{summ['ridge_count']},{summ['total']},{summ['frac_ridge']},0.75\n")

    # Contours summary
    contours_txt = os.path.join(OUT_DIR, 'ven_ridge_contours_summary.txt')
    with open(contours_txt, 'w', encoding='utf-8') as f:
        f.write("VEN ridge contour summary (argmax and ridge fraction >=0.75)\n")
        for mode in ('balanced','discovery','grounded'):
            arrs = arrays.get(mode, [])
            if not arrs:
                f.write(f"- {mode}: no arrays found\n")
                continue
            best = max(arrs, key=lambda a: len(a)*len(a[0]))
            Z = np.array(best, dtype=float)
            i, j, zmax = argmax_coords(Z)
            r_val = r_axis[j] if (isinstance(r_axis, list) and j < len(r_axis)) else None
            a_val = a_axis[i] if (isinstance(a_axis, list) and i < len(a_axis)) else None
            ridge_frac = float(np.sum(Z >= 0.75)/Z.size) if Z.size else 0.0
            f.write(f"- {mode}: max={zmax:.4f} at indices (alpha_idx={i}, r_idx={j}) -> (alpha={a_val}, r={r_val}); ridge_frac>=0.75={ridge_frac:.3f}\n")

    print(f"[artifacts] {table_csv} | {contours_txt}")

if __name__ == "__main__":
    main()
